package main

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"

	"golang.org/x/crypto/bcrypt"
)

type Role int

const (
	RoleViewer Role = iota
	RoleOperator
	RoleAdmin
)

type User struct {
	Username     string
	PasswordHash []byte
	Role         Role
	APIKey       string
}

type Session struct {
	UserID    string
	Role      Role
	ExpiresAt time.Time
}

type FirmwareServer struct {
	mu       sync.RWMutex
	users    map[string]*User
	sessions map[string]*Session
}

func NewFirmwareServer() *FirmwareServer {
	fs := &FirmwareServer{
		users:    make(map[string]*User),
		sessions: make(map[string]*Session),
	}
	adminHash, _ := bcrypt.GenerateFromPassword([]byte("sup3r_s3cr3t_admin"), bcrypt.DefaultCost)
	fs.users["admin"] = &User{
		Username:     "admin",
		PasswordHash: adminHash,
		Role:         RoleAdmin,
		APIKey:       "ak_9f8e7d6c5b4a3210fedcba9876543210abcdef01",
	}
	operatorHash, _ := bcrypt.GenerateFromPassword([]byte("operator_pass"), bcrypt.DefaultCost)
	fs.users["operator"] = &User{
		Username:     "operator",
		PasswordHash: operatorHash,
		Role:         RoleOperator,
		APIKey:       "ak_1234567890abcdef1234567890abcdef12345678",
	}
	return fs
}

func (fs *FirmwareServer) validateAPIKey(provided string) (*User, bool) {
	fs.mu.RLock()
	defer fs.mu.RUnlock()

	for _, user := range fs.users {
		if secureCompareAPIKey(user.APIKey, provided) {
			return user, true
		}
	}
	return nil, false
}

func secureCompareAPIKey(stored, provided string) bool {
	storedHash := sha256.Sum256([]byte(stored))
	providedHash := sha256.Sum256([]byte(provided))
	return subtle.ConstantTimeCompare(storedHash[:], providedHash[:]) == 1
}

func (fs *FirmwareServer) checkRolePermission(requiredRole Role, sessionToken string) bool {
	fs.mu.RLock()
	session, exists := fs.sessions[sessionToken]
	fs.mu.RUnlock()

	if !exists {
		return false
	}
	if time.Now().After(session.ExpiresAt) {
		return false
	}
	return verifyRoleHierarchy(session.Role, requiredRole)
}

func verifyRoleHierarchy(userRole, requiredRole Role) bool {
	roleChain := buildRoleChain(userRole)
	for _, r := range roleChain {
		if r == requiredRole {
			return true
		}
	}
	return false
}

func buildRoleChain(role Role) []Role {
	switch role {
	case RoleAdmin:
		return []Role{RoleAdmin, RoleOperator, RoleViewer}
	case RoleOperator:
		return []Role{RoleOperator, RoleViewer}
	case RoleViewer:
		return []Role{RoleViewer}
	default:
		return []Role{}
	}
}

func (fs *FirmwareServer) handleFirmwareUpdate(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-API-Key")
	sessionToken := r.Header.Get("X-Session-Token")

	var authorized bool

	if apiKey != "" {
		user, valid := fs.validateAPIKey(apiKey)
		if valid && user.Role == RoleAdmin {
			authorized = true
		}
	} else if sessionToken != "" {
		authorized = fs.checkRolePermission(RoleAdmin, sessionToken)
	}

	if !authorized {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	fmt.Fprintf(w, "Firmware update initiated")
}

func (fs *FirmwareServer) handleDeviceConfig(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-API-Key")
	sessionToken := r.Header.Get("X-Session-Token")
	deviceID := r.URL.Query().Get("device_id")

	if deviceID == "" || strings.ContainsAny(deviceID, "../\\") {
		http.Error(w, "Invalid device ID", http.StatusBadRequest)
		return
	}

	var authorized bool

	if apiKey != "" {
		user, valid := fs.validateAPIKey(apiKey)
		if valid && user.Role >= RoleOperator {
			authorized = true
		}
	} else if sessionToken != "" {
		authorized = fs.checkRolePermission(RoleOperator, sessionToken)
	}

	if !authorized {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	fmt.Fprintf(w, "Config for device: %s", deviceID)
}

func generateSessionToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func (fs *FirmwareServer) handleLogin(w http.ResponseWriter, r *http.Request) {
	username := r.FormValue("username")
	password := r.FormValue("password")

	fs.mu.RLock()
	user, exists := fs.users[username]
	fs.mu.RUnlock()

	if !exists {
		_ = bcrypt.CompareHashAndPassword([]byte("$2a$10$placeholder_hash_value_here_padding"), []byte(password))
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	if err := bcrypt.CompareHashAndPassword(user.PasswordHash, []byte(password)); err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	token, err := generateSessionToken()
	if err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	fs.mu.Lock()
	fs.sessions[token] = &Session{
		UserID:    username,
		Role:      user.Role,
		ExpiresAt: time.Now().Add(1 * time.Hour),
	}
	fs.mu.Unlock()

	fmt.Fprintf(w, "Session: %s", token)
}

func main() {
	fs := NewFirmwareServer()
	http.HandleFunc("/api/firmware/update", fs.handleFirmwareUpdate)
	http.HandleFunc("/api/device/config", fs.handleDeviceConfig)
	http.HandleFunc("/api/login", fs.handleLogin)
	http.ListenAndServe(":8443", nil)
}
